import { useMemo } from 'react';

export interface DataView {
  loading: boolean;
  error: Error | null;
  isEmpty: boolean;
  skipped?: boolean;
}

export interface UseCommercialResultsFullPageEmptyStateResult {
  showFullPageEmpty: boolean;
}

export const useCommercialResultsFullPageEmptyState = (
  views: DataView[],
): UseCommercialResultsFullPageEmptyStateResult => {
  const showFullPageEmpty = useMemo(() => {
    const activeViews = views.filter((v) => !v.skipped);
    return (
      activeViews.length > 0 &&
      !activeViews.some((v) => v.loading) &&
      activeViews.every((v) => v.isEmpty && !v.error)
    );
  }, [views]);

  return { showFullPageEmpty };
};
